// src/battle/setup/buildBattleSetup.js
// Everything a tactical battle needs, computed ONCE from the strategic game (Tactical Battles plan
// §4.2, §7.3). The sim never reads GameState: it gets this plain object (seed, map, structures,
// armies, and the exact multipliers auto-resolve would have used), which is also what makes it
// replayable anywhere — worker, test, or server.
import { REGIONS_DATA } from '../../data/regions';
import { getCombatWidth, getTerrainCombatModifier, TERRAIN_COMBAT_MODIFIERS } from '../../data/terrain';
import { REGION_COORDINATES } from '../../data/regionCoordinates';
import { canSeeRegionDetails } from '../../engine/intel';
import { getRosterCombatMultiplier } from '../../data/unitClasses';
import { getDepositsFor } from '../../data/deposits';
import { getRegionModifier } from '../../engine/modifiers/sheet';
import { validateInvasion, getInvasionBattleContext, getBattlePowers, validateAmphibious, getAmphibiousBattleContext } from '../../engine/invasion';
import { validateFieldAttack, getFieldBattleContext, FORT_BATTLE_LEVEL } from '../../engine/fieldBattle';
import { validateFleetAttack, getFleetBattleContext } from '../../engine/navalBattle';
import { getDefenseArmies, getDefenseBattleContext } from '../../engine/defense';
import { generateMap, TILE, LANDING_SEA_COLS } from './mapgen';
import { BATTLE_TYPES, battleTypeOf, RAID_TYPES, RAID_LOOT_NEEDED, RAID_LOOT_TARGETS, SACK_BURN_NEEDED } from './battleType';
import { getTiles } from '../../data/geo/tiles';
import { tileContextOf } from './tileContext';
import { unitTile } from '../../engine/armies';
import { BUILDING_CATEGORIES, getCategoryTierName } from '../../data/buildings';
import { polarX, polarY } from '../sim/fixed';
import { Q, SIDE_ATTACKER, secondsToTicks } from '../sim/constants';
import { placeCity, cityKeepInset } from './cityBattle';
import { cityManifestOf, cityDamageOf } from '../../engine/cityManifest';
import { buildEconomySetup } from './economySetup';
import { battleInputs } from '../../engine/battleInputs';
import { getTechAgeId } from '../../engine/nationState';
import { isRaidKind, queuedRaidArmies, raidSpecOf, raidBattleContext } from '../../engine/raidBattle';
import { interceptArmies, interceptArgs } from '../../engine/aiLanding';
import { ECONOMY_FIELD_TICKS, ECONOMY_SIEGE_TICKS } from '../sim/constants';

// Bumped whenever the sim's rules change, so an old checkpoint restarts rather than replaying
// under different rules (v2: garrisons, v3: the region's buildings on the battlefield, v4: the real
// city from its manifest, cityBattle.js; v5: the battle economy, economySetup.js; v6: phase R3, the
// raid and sack types, the pursuit after a field battle, forts and generals on the field).
export const SETUP_VERSION = 6;
export const SIDE_COLORS = ['#3b82f6', '#f97316']; // colour-blind-safe blue vs orange
const TERRITORY_RADIUS = 14 * Q;

const centre = (t) => t * Q + (Q >> 1);

export const buildStructures = ({ keepTile, fortLevel, isCapital }) => {
  // An unfortified region's "keep" is just its town: it only shoots back once it has real defenses.
  const keep = {
    id: 'keep', kind: 'keep', x: centre(keepTile.x), y: centre(keepTile.y), radius: Math.round(1.5 * Q),
    maxHp: Math.round((1500 + 750 * fortLevel) * (isCapital ? 1.5 : 1)), walls: fortLevel >= 2,
    range: 8 * Q, attackTicks: secondsToTicks(1.5), damage: fortLevel > 0 ? 8 + 6 * fortLevel : 0, cooldown: 0, alive: true
  };
  keep.hp = keep.maxHp;
  const towerCount = Math.min(6, Math.floor(fortLevel / 2) + (isCapital ? Math.max(0, 2 - Math.floor(fortLevel / 2)) : 0));
  const towers = Array.from({ length: towerCount }, (_, i) => {
    // Spread across the keep's west-facing arc (the side the attacker comes from).
    const angle = (128 + Math.round((i - (towerCount - 1) / 2) * 26)) & 255;
    const hp = 800 + 200 * fortLevel;
    return {
      id: `tower${i}`, kind: 'tower', x: keep.x + polarX(angle, 6 * Q), y: keep.y + polarY(angle, 6 * Q), radius: Math.round(0.8 * Q),
      maxHp: hp, hp, range: 7 * Q, attackTicks: secondsToTicks(1.5), damage: 8 + 4 * fortLevel, cooldown: 0, alive: true
    };
  });
  return [keep, ...towers];
};

// The province's built buildings (other than its fortifications, which are the keep and towers),
// as a list of { category, tier, name } for the battlefield.
export const getRegionBattleBuildings = (region) => Object.entries(region?.buildings?.categories || {})
  .filter(([category, tier]) => tier >= 0 && category !== 'defense' && BUILDING_CATEGORIES[category])
  .map(([category, tier]) => ({ category, tier, name: getCategoryTierName(category, tier) || BUILDING_CATEGORIES[category].label }));

// Stands each building on open ground around the keep, mostly on the defender's side of it, and
// turns its tile into a building so troops walk around it.
// A besiegers' camp for a sally: three siege engines and the camp itself, east of the field, as
// razable 'building' structures (buildings.js) the garrison must burn (battleType.js).
const placeCamp = (map) => {
  const { w, h, tiles } = map;
  const cx = Math.floor(w * 0.78); const cy = Math.floor(h / 2);
  const spots = [[cx, cy, 'camp', 'Siege camp', 900], [cx - 4, cy - 5, 'engine', 'Siege engine', 500], [cx - 5, cy + 1, 'engine', 'Siege engine', 500], [cx - 3, cy + 6, 'engine', 'Siege engine', 500]];
  return spots.map(([x, y, category, name, hp], i) => {
    const tx = Math.max(2, Math.min(w - 3, x)); const ty = Math.max(2, Math.min(h - 3, y));
    tiles[ty * w + tx] = TILE.BUILDING;
    return { id: `${category}_${i}`, kind: 'building', category, name, tier: 1, x: centre(tx), y: centre(ty), radius: Math.round(0.9 * Q), maxHp: hp, hp, range: 0, attackTicks: secondsToTicks(1.5), damage: 0, cooldown: 0, alive: true };
  });
};

// A raid's loot (battleType.js): a depot, the fields' stores and a trade post on the defender's
// side of the field, razable 'building' structures flagged `loot` the raiders must burn.
export const LOOT_TARGETS = [['depot', 'Depot', 300], ['fields', 'Fields and stores', 260], ['tradepost', 'Trade post', 280]];
// Spread across the defender's front (north, centre, south), ahead of its line: one force cannot
// cover them all, so the defender must come out and the raiders must get through.
const placeLoot = (map) => {
  const { w, h, tiles, keep } = map;
  const spread = Math.max(4, Math.floor(h * 0.3));
  const spots = [[-17, -spread], [-13, 0], [-17, spread]];
  return LOOT_TARGETS.slice(0, RAID_LOOT_TARGETS).map(([category, name, hp], i) => {
    let tx = Math.max(2, Math.min(w - 3, keep.x + spots[i][0])); const ty = Math.max(2, Math.min(h - 3, keep.y + spots[i][1]));
    for (let k = 0; k < 12 && tiles[ty * w + tx] !== TILE.OPEN && tiles[ty * w + tx] !== TILE.SAND; k++) tx = Math.min(w - 3, tx + 1);
    tiles[ty * w + tx] = TILE.BUILDING;
    return { id: `loot_${category}`, kind: 'building', category, name, tier: 1, loot: true, x: centre(tx), y: centre(ty), radius: Math.round(0.9 * Q), maxHp: hp, hp, range: 0, attackTicks: secondsToTicks(1.5), damage: 0, cooldown: 0, alive: true };
  });
};

const placeBuildings = (map, list) => {
  if (!list.length) return [];
  const { w, h, tiles, keep } = map;
  const out = [];
  const taken = new Set();
  list.forEach((b, i) => {
    for (let tryN = 0; tryN < 48; tryN++) {
      const angle = ((i * 0.9 + tryN * 0.37) % (Math.PI * 1.6)) - Math.PI * 0.8; // east, north and south of the keep
      const r = 6 + (tryN % 4);
      const tx = Math.round(keep.x + Math.cos(angle) * r); const ty = Math.round(keep.y + Math.sin(angle) * r);
      if (tx < 2 || ty < 2 || tx >= w - 2 || ty >= h - 2) continue;
      const k = ty * w + tx;
      if (tiles[k] !== TILE.OPEN || taken.has(k)) continue;
      taken.add(k); tiles[k] = TILE.BUILDING;
      const hp = 600 + 150 * b.tier;
      out.push({ id: `b_${b.category}`, kind: 'building', category: b.category, name: b.name, tier: b.tier, x: centre(tx), y: centre(ty), radius: Math.round(0.9 * Q), maxHp: hp, hp, range: 0, attackTicks: secondsToTicks(1.5), damage: 0, cooldown: 0, alive: true });
      return;
    }
  });
  return out;
};

// Pure: works from plain inputs, so tests, the sandbox and the parity harness can build battles
// without a whole game state.
export const buildSetupFromArmies = ({
  regionId, terrain, seed, attackerUnits, defenderUnits,
  attackerAgeId = 'bronze', defenderAgeId = 'bronze', generals = {},
  fortLevel = 0, isCapital = false, infrastructure = 0, deposits = [],
  defenseReduction = 1, isAttackingFortification = fortLevel > 0, attackerPenaltyMultiplier = 1,
  attackerNationId = 'attacker', defenderNationId = 'defender',
  controllers = ['player', 'ai'], difficultyId = 'prince',
  powers = [[{ id: 'rallyCry' }], [{ id: 'rallyCry' }]], reinforcements = [[], []], intel = { attackerSeesDefender: true },
  landing = false, regionBuildings = [], tileContext = null, sally = false, city = fortLevel > 0 || isCapital, fromTile = null, battleType = null,
  raid = false, // raiders come for loot (battleType.js raid, or sack on a city): the one light battle
  cityManifest = null, cityDamage = null, // the real city (src/engine/cityManifest.js): its houses, walls and landmarks stand on the field
  combatWidth: combatWidthOverride = null, // a bigger field for the large-battle presets and the benchmark (src/battle/bench/benchScenario.js)
  // The battle economy (phase R1, economySetup.js): workers, resources, buildings and training. The
  // campaign's battles turn it on; a setup without it plays exactly as before (tests, parity, bench).
  // `economyInputs`: { supply: [a, d], development: [a, d] } in 0..1 (else the units' supply meters).
  economy = false, economyInputs = null
}) => {
  const combatWidth = combatWidthOverride || getCombatWidth(terrain);
  const naval = battleType === 'naval';
  const type = battleType || battleTypeOf({ raid, landing, sally, city, fortLevel, tileContext, fromTile });
  const raiding = RAID_TYPES.has(type);
  const realCity = !naval && type !== 'sally' && type !== 'raid' && cityManifest?.structures?.length ? cityManifest : null;
  const map = generateMap({ regionId, terrain, combatWidth, pointCount: naval ? 0 : deposits.length, roads: 1 + (infrastructure >= 5 ? 1 : 0) + (infrastructure >= 8 ? 1 : 0) + (tileContext?.roads || 0), landing, tileContext, naval, ...(realCity ? { keepInset: cityKeepInset(realCity) } : {}) });
  // A siege in progress (sieges.js) has already battered the walls: the keep starts at that HP.
  // A sea battle has one structure: the defender's anchorage, an unwalled keep the AI steers for and the renderer leaves out.
  let cityInfo = null;
  let structures;
  if (naval) structures = buildStructures({ keepTile: map.keep, fortLevel: 0, isCapital: false });
  else if (realCity) {
    const keepStructures = buildStructures({ keepTile: map.keep, fortLevel, isCapital });
    const placed = placeCity({ map, manifest: realCity, damage: cityDamage, fortLevel, keepStructures });
    structures = placed.structures;
    cityInfo = placed.city;
  } else if (type === 'raid') structures = [...buildStructures({ keepTile: map.keep, fortLevel: 0, isCapital: false }), ...placeLoot(map)];
  else structures = [...buildStructures({ keepTile: map.keep, fortLevel, isCapital }), ...placeBuildings(map, regionBuildings), ...(type === 'sally' ? placeCamp(map) : []), ...(type === 'sack' ? placeLoot(map) : [])];
  // A sack burns the town: its buildings and houses are the loot (a town without a manifest gets the raid's targets).
  if (type === 'sack' && realCity) structures.forEach((st) => { if ((st.kind === 'building' || st.kind === 'house') && !st.ruinedAtStart && st.alive) st.loot = true; });
  // Every land battle but a raid has full base-building (decision 36): raiders come to plunder, not to stay.
  const ecoSetup = economy && !naval && !raiding ? buildEconomySetup({
    map, terrain, tileContext, regionKey: regionId, structures, city: cityInfo, inputs: economyInputs,
    sides: [{ units: attackerUnits }, { units: defenderUnits }], ageIds: [attackerAgeId, defenderAgeId]
  }) : null;
  if (tileContext && tileContext.hpRatio < 1) structures.forEach((st) => { if (st.kind === 'keep' || st.kind === 'tower') st.hp = Math.max(1, Math.round(st.maxHp * tileContext.hpRatio)); });
  const points = map.points.map((p, i) => ({ id: `p_${deposits[i]}`, kind: 'deposit', resId: deposits[i], x: centre(p.x), y: centre(p.y), owner: 1, progress: 0, capturingSide: -1 }));
  // A landing's beachhead: a point on the sand the invaders must hold (battleType.js).
  if (type === 'landing') points.push({ id: 'beachhead', kind: 'beachhead', resId: null, x: centre(LANDING_SEA_COLS + 3), y: centre(Math.floor(map.h / 2)), owner: 1, progress: 0, capturingSide: -1 });
  return {
    version: SETUP_VERSION,
    seed: seed >>> 0,
    regionId,
    terrain,
    combatWidth,
    // The clock by battle type (battleType.js): a field battle is fast, a siege gives the engines time.
    battleType: type,
    // With an economy the clocks are the master plan's (6.1): a city assault 30 minutes, the rest 15.
    // A landing is fought as a city assault (6.1): the 30-minute clock; a sally the field's 15.
    limitTicks: ecoSetup ? (type === 'assault' || type === 'landing' ? ECONOMY_SIEGE_TICKS : ECONOMY_FIELD_TICKS) : BATTLE_TYPES[type].limitTicks,
    // What the raiders must burn before they get away (battleType.js).
    ...(raiding ? { raid: { needed: type === 'sack' ? SACK_BURN_NEEDED : RAID_LOOT_NEEDED } } : {}),
    map,
    tile: tileContext?.tile ?? null,
    structures,
    // The real city (cityBattle.js): its id, town model, scale and the defender's housing cap
    // (houses plus the town hall, master plan 6.3; the battle economy reads it from phase R1).
    city: cityInfo,
    economy: ecoSetup,
    points,
    territoryRadius: TERRITORY_RADIUS,
    supplyCap: 200 + 30 * Math.max(0, infrastructure),
    startSupply: [100, 100 + (points.length ? 50 : 0)],
    sides: [
      { nationId: attackerNationId, ageId: attackerAgeId, color: SIDE_COLORS[0], units: attackerUnits.map((u) => ({ ...u })), reinforcements: reinforcements[0] || [] },
      { nationId: defenderNationId, ageId: defenderAgeId, color: SIDE_COLORS[1], units: defenderUnits.map((u) => ({ ...u })), reinforcements: reinforcements[1] || [] }
    ],
    // RoN attrition inside the defender's territory: terrain's own attrition factor, raised by
    // fortifications (towers' "patriotism").
    attritionPerMinute: 0.006 * (TERRAIN_COMBAT_MODIFIERS[terrain]?.attritionMult || 1) * (1 + 0.1 * fortLevel),
    powers,
    modifiers: {
      // The same numbers resolveBattle folds into each side's baseMultiplier, minus the walls
      // reduction — applied in the sim only to defenders actually fighting from inside their
      // territory (src/battle/sim/combat.js).
      attackerBase: attackerPenaltyMultiplier * getRosterCombatMultiplier(attackerAgeId, defenderAgeId) * getTerrainCombatModifier(terrain).attackerMult,
      defenderBase: getRosterCombatMultiplier(defenderAgeId, attackerAgeId),
      defenseReduction,
      isAttackingFortification,
      intel
    },
    generals,
    controllers,
    difficultyId
  };
};

// Which map edge a neighbouring province's troops enter from. The battlefield is laid out with
// the attacker's own origin to the WEST; every other neighbour keeps its real bearing relative to
// that (rotation only, never mirrored), then is snapped to the side's own edges.
export const reinforcementEdge = (targetRegionId, fromRegionId, neighbourRegionId, side) => {
  const t = REGION_COORDINATES[targetRegionId]; const f = REGION_COORDINATES[fromRegionId]; const n = REGION_COORDINATES[neighbourRegionId];
  if (!t || !f || !n) return side === SIDE_ATTACKER ? 'W' : 'E';
  const bearing = (c) => Math.atan2(c.lat - t.lat, (c.lng - t.lng) * Math.cos((t.lat * Math.PI) / 180)) * 180 / Math.PI;
  let m = bearing(n) + (180 - bearing(f));
  m = ((m % 360) + 540) % 360 - 180; // -180..180, 180/-180 = west, 0 = east, 90 = north
  const edge = Math.abs(m) >= 135 ? 'W' : Math.abs(m) <= 45 ? 'E' : m > 0 ? 'N' : 'S';
  if (side === SIDE_ATTACKER && edge === 'E') return m >= 0 ? 'N' : 'S';
  if (side !== SIDE_ATTACKER && edge === 'W') return m >= 0 ? 'N' : 'S';
  return edge;
};

const toReinforcements = (state, pb, sources, side) => (sources || []).map((src) => ({
  regionId: src.regionId,
  name: REGIONS_DATA[src.regionId]?.name || src.regionId,
  edge: reinforcementEdge(pb.targetRegionId, pb.fromRegionId, src.regionId, side),
  units: src.unitIds.map((id) => state.units[id]).filter(Boolean).map((u) => ({ ...u }))
})).filter((r) => r.units.length);

// The battle for a pending invasion, rebuilt purely from game state + the pending record — so a
// battle interrupted by an app restart rebuilds the identical setup and resumes.
// An AI assault on one of the player's garrisons (src/engine/defense.js): the same battlefield,
// with the player commanding the defenders and the AI's real and synthetic troops attacking.
const buildDefenseSetup = (state, pb) => {
  const def = (state.pendingDefenses || []).find((d) => d.id === pb.defenseId);
  const region = state.regions[pb.targetRegionId];
  if (!def || !region) return null;
  const armies = getDefenseArmies(state, { ...def, attackerUnitIds: pb.attackerUnitIds, synthetic: pb.synthetic, defenderUnitIds: pb.defenderUnitIds });
  if (!armies.attackerUnits.length || !armies.defenderUnits.length) return null;
  const ctx = getDefenseBattleContext(state, def);
  // The same campaign inputs as the auto-resolve (battleInputs.js): conditioned morale, the city's
  // militia fixed when the battle began (pb.militia), the stockpiles' supply and development.
  const ins = battleInputs(state, { attackerUnits: armies.attackerUnits, defenderUnits: armies.defenderUnits, cityId: pb.targetRegionId, fromRegionId: def.fromRegionId, militia: pb.militia || [] });
  const regionData = REGIONS_DATA[pb.targetRegionId] || {};
  const fromUnit = armies.attackerUnits.find((u) => !u.synthetic && state.units[u.id]);
  return buildSetupFromArmies({
    tileContext: tileContextOf(state, region.tile, { fromTile: fromUnit ? unitTile(state, state.units[fromUnit.id]) : state.regions[def.fromRegionId]?.tile ?? null, city: region }),
    regionId: pb.targetRegionId,
    terrain: ctx.terrain,
    seed: pb.seed,
    attackerUnits: ins.attackerUnits,
    defenderUnits: ins.defenderUnits,
    attackerAgeId: ctx.attackerAgeId,
    defenderAgeId: ctx.defenderAgeId,
    generals: ctx.generals,
    fortLevel: Math.max(0, Math.round(ctx.fortLevel)),
    isCapital: !!regionData.isCapital,
    infrastructure: region.currentInfrastructure || 0,
    deposits: getDepositsFor(regionData.startOwner),
    defenseReduction: ctx.defenderDamageReductionMultiplier,
    isAttackingFortification: ctx.isAttackingFortification,
    attackerNationId: pb.attackerNationId,
    defenderNationId: state.playerNationId,
    controllers: ['ai', 'player'],
    difficultyId: state.difficultyId || 'prince',
    powers: [
      getBattlePowers(state, pb.attackerNationId, ctx.attackerAgeId, armies.attackerUnits, { allowNuclear: false }),
      getBattlePowers(state, state.playerNationId, ctx.defenderAgeId, armies.defenderUnits, { allowNuclear: true })
    ],
    reinforcements: [[], toReinforcements(state, pb, pb.defenderReinforcements, 1)],
    // The AI does no espionage; the defender sees its own land regardless.
    intel: { attackerSeesDefender: false },
    regionBuildings: getRegionBattleBuildings(region),
    cityManifest: cityManifestOf(state, pb.targetRegionId),
    cityDamage: cityDamageOf(region),
    economy: true, // every assault is a full RTS battle (decision 23; phase R1)
    economyInputs: ins.economyInputs
  });
};

// A field or sea battle an AI started against the player (battleQueue.js) is gated as the
// aggressor's attack: the same gate, from its side.
const gateOf = (state, pb) => (pb.attackerNationId && pb.attackerNationId !== state.playerNationId
  ? { ...state, playerNationId: pb.attackerNationId, techAgeId: getTechAgeId(state, pb.attackerNationId) }
  : state);

// A commanded amphibious landing (T9): the invaders come ashore on a beach at the west edge, with
// their fleet's guns (two Naval Bombardment salvos) covering the shore half of the field. Their
// own reinforcements can't follow by sea; the defender's neighbours can still march in.
const buildAmphibiousSetup = (state, pb) => {
  // An AI landing on the player's coast (src/engine/aiLanding.js) is gated as the aggressor's.
  const gate = gateOf(state, pb);
  const aiLands = gate !== state;
  const v = validateAmphibious(gate, pb.navalUnitId, pb.targetRegionId, { ignoreCost: true, ignoreBattleLocks: true });
  if (!v.ok) return null;
  const attackerUnits = v.embarkedLandUnits.filter((u) => pb.attackerUnitIds.includes(u.id));
  const defenderUnits = v.defenderLandUnits.filter((u) => pb.defenderUnitIds.includes(u.id));
  if (!attackerUnits.length || !defenderUnits.length) return null;
  const ctx = getAmphibiousBattleContext(gate, { ...v, hasBeachhead: pb.hasBeachhead ?? v.hasBeachhead }, defenderUnits);
  const ins = battleInputs(state, { attackerUnits, defenderUnits, cityId: pb.targetRegionId, fromRegionId: pb.fromRegionId, militia: pb.militia || [] });
  const regionData = REGIONS_DATA[pb.targetRegionId] || {};
  const fortLevel = (v.targetRegion.defenseLevel || 0) + getRegionModifier(state, pb.targetRegionId, 'local.fortLevel').total;
  return buildSetupFromArmies({
    tileContext: tileContextOf(state, v.targetRegion.tile, { fromTile: unitTile(state, v.navalUnit), city: v.targetRegion }),
    regionId: pb.targetRegionId,
    terrain: ctx.terrain,
    seed: pb.seed,
    attackerUnits: ins.attackerUnits,
    defenderUnits: ins.defenderUnits,
    attackerAgeId: ctx.attackerAgeId,
    defenderAgeId: ctx.defenderAgeId,
    generals: ctx.generals || {},
    fortLevel: Math.max(0, Math.round(fortLevel)),
    isCapital: !!regionData.isCapital,
    infrastructure: v.targetRegion.currentInfrastructure || 0,
    deposits: getDepositsFor(regionData.startOwner),
    defenseReduction: ctx.defenderDamageReductionMultiplier,
    isAttackingFortification: ctx.isAttackingFortification,
    attackerPenaltyMultiplier: ctx.attackerPenaltyMultiplier,
    attackerNationId: gate.playerNationId,
    defenderNationId: v.targetRegion.owner,
    controllers: aiLands ? ['ai', 'player'] : ['player', 'ai'],
    difficultyId: state.difficultyId || 'prince',
    powers: [
      [...getBattlePowers(state, gate.playerNationId, ctx.attackerAgeId, attackerUnits, { allowNuclear: !aiLands }), { id: 'navalBombardment', uses: 2 }],
      getBattlePowers(state, v.targetRegion.owner, ctx.defenderAgeId, defenderUnits, { allowNuclear: aiLands })
    ],
    reinforcements: [[], toReinforcements(state, pb, pb.defenderReinforcements, 1)],
    intel: { attackerSeesDefender: aiLands ? false : canSeeRegionDetails(state, pb.targetRegionId) },
    landing: true,
    regionBuildings: getRegionBattleBuildings(v.targetRegion),
    cityManifest: cityManifestOf(state, pb.targetRegionId),
    cityDamage: cityDamageOf(v.targetRegion),
    economy: true,
    economyInputs: ins.economyInputs
  });
};

// A field battle (fieldBattle.js): two stacks on open ground. The defender's camp stands for the
// keep (an unfortified town fires nothing); the tile and its neighbours shape the field.
const buildFieldSetup = (state, pb) => {
  const gate = gateOf(state, pb);
  const v = validateFieldAttack(gate, pb.fromRegionId, pb.tile, { ignoreCost: true, ignoreBattleLocks: true });
  if (!v.ok) return null;
  // A sally: the attackers come out of a besieged city onto its ring (battleType.js).
  const from = state.regions[pb.fromRegionId];
  const sally = !!from?.siege?.by && from.tile != null && getTiles().neighbors[from.tile].includes(pb.tile);
  const attackerUnits = v.attackerUnits.filter((u) => pb.attackerUnitIds.includes(u.id));
  const defenderUnits = v.defenderUnits.filter((u) => pb.defenderUnitIds.includes(u.id));
  if (!attackerUnits.length || !defenderUnits.length) return null;
  const ctx = getFieldBattleContext(gate, { ...v, attackerUnits, defenderUnits });
  const ins = battleInputs(state, { attackerUnits, defenderUnits, fromRegionId: pb.fromRegionId });
  return buildSetupFromArmies({
    tileContext: tileContextOf(state, pb.tile, { fromTile: v.fromTile }),
    fromTile: v.fromTile, sally, city: false,
    regionId: pb.targetRegionId,
    terrain: ctx.terrain,
    seed: pb.seed,
    attackerUnits: ins.attackerUnits,
    defenderUnits: ins.defenderUnits,
    attackerAgeId: ctx.attackerAgeId,
    defenderAgeId: ctx.defenderAgeId,
    generals: ctx.generals || {},
    // A Fort on the tile stands on the field as a walled keep with a tower; the garrison may man it (decision 34).
    fortLevel: ctx.isAttackingFortification ? FORT_BATTLE_LEVEL : 0,
    isCapital: false,
    infrastructure: 0,
    deposits: [],
    defenseReduction: ctx.defenderDamageReductionMultiplier,
    isAttackingFortification: ctx.isAttackingFortification,
    attackerPenaltyMultiplier: ctx.attackerPenaltyMultiplier,
    attackerNationId: gate.playerNationId,
    defenderNationId: v.defenderNationId,
    controllers: pb.playerSide === 'defender' ? ['ai', 'player'] : ['player', 'ai'],
    difficultyId: state.difficultyId || 'prince',
    powers: [getBattlePowers(state, gate.playerNationId, ctx.attackerAgeId, attackerUnits, { allowNuclear: gate.playerNationId === state.playerNationId }), getBattlePowers(state, v.defenderNationId, ctx.defenderAgeId, defenderUnits, { allowNuclear: v.defenderNationId === state.playerNationId })],
    reinforcements: [[], []],
    intel: { attackerSeesDefender: true },
    regionBuildings: [],
    economy: true, // full base-building in field battles too (decision 36)
    economyInputs: ins.economyInputs
  });
};

// A sea battle (navalBattle.js): the fleets on `fromTile` against the enemy fleets on `tile`.
const buildNavalSetup = (state, pb) => {
  const gate = gateOf(state, pb);
  const v = validateFleetAttack(gate, pb.fromTile, pb.tile, { ignoreCost: true, ignoreBattleLocks: true });
  if (!v.ok) return null;
  const attackerUnits = v.attackerUnits.filter((u) => pb.attackerUnitIds.includes(u.id));
  const defenderUnits = v.defenderUnits.filter((u) => pb.defenderUnitIds.includes(u.id));
  if (!attackerUnits.length || !defenderUnits.length) return null;
  const ctx = getFleetBattleContext(gate, { ...v, attackerUnits, defenderUnits });
  return buildSetupFromArmies({
    tileContext: tileContextOf(state, pb.tile, { fromTile: v.fromTile }),
    fromTile: v.fromTile, battleType: 'naval',
    regionId: pb.targetRegionId,
    terrain: ctx.terrain,
    seed: pb.seed,
    attackerUnits, defenderUnits,
    attackerAgeId: ctx.attackerAgeId, defenderAgeId: ctx.defenderAgeId,
    generals: ctx.generals || {},
    fortLevel: 0, isCapital: false, infrastructure: 0, deposits: [],
    defenseReduction: 1, isAttackingFortification: false, attackerPenaltyMultiplier: 1,
    attackerNationId: gate.playerNationId, defenderNationId: v.defenderNationId,
    controllers: pb.playerSide === 'defender' ? ['ai', 'player'] : ['player', 'ai'], difficultyId: state.difficultyId || 'prince',
    powers: [[], []], reinforcements: [[], []], intel: { attackerSeesDefender: true }, regionBuildings: []
  });
};

// A raid or a sack against the player (src/engine/raidBattle.js): the raiders' party on the tile (or
// before the town) against the player's troops there; the light battle, no base-building. A sack
// stands the real town (its buildings and houses are the loot) with its militia.
const buildRaidSetup = (state, pb) => {
  const def = (state.pendingDefenses || []).find((d) => d.id === pb.defenseId);
  if (!def) return null;
  const armies = queuedRaidArmies(state, { ...def, attackerUnitIds: pb.attackerUnitIds, defenderUnitIds: pb.defenderUnitIds });
  const spec = raidSpecOf(state, def, armies);
  if (!spec.attackerUnits.length) return null;
  const sack = def.kind === 'sack';
  const city = sack ? state.regions[def.cityId] : null;
  const ctx = raidBattleContext(state, spec);
  const ins = battleInputs(state, { attackerUnits: spec.attackerUnits, defenderUnits: spec.defenderUnits, cityId: sack ? def.cityId : null, militia: pb.militia || def.militia || [] });
  if (!ins.defenderUnits.length) return null;
  const tile = sack ? city?.tile ?? def.tile : def.tile;
  return buildSetupFromArmies({
    tileContext: tileContextOf(state, tile, { fromTile: def.fromTile ?? null, city: sack ? city : null }),
    fromTile: def.fromTile ?? null, raid: true, city: sack,
    regionId: def.regionId ?? `t${tile}`,
    terrain: ctx.terrain,
    seed: pb.seed,
    attackerUnits: ins.attackerUnits,
    defenderUnits: ins.defenderUnits,
    attackerAgeId: ctx.attackerAgeId,
    defenderAgeId: ctx.defenderAgeId,
    generals: ctx.generals || {},
    fortLevel: sack ? Math.max(0, Math.round(city?.defenseLevel || 0)) : 0,
    isCapital: false,
    infrastructure: 0,
    deposits: [],
    defenseReduction: ctx.defenderDamageReductionMultiplier,
    isAttackingFortification: ctx.isAttackingFortification,
    attackerNationId: def.aggressorId,
    defenderNationId: state.playerNationId,
    controllers: ['ai', 'player'],
    difficultyId: state.difficultyId || 'prince',
    powers: [[], getBattlePowers(state, state.playerNationId, ctx.defenderAgeId, spec.defenderUnits, { allowNuclear: false })],
    reinforcements: [[], []],
    intel: { attackerSeesDefender: false },
    regionBuildings: sack ? getRegionBattleBuildings(city) : [],
    cityManifest: sack ? cityManifestOf(state, def.cityId) : null,
    cityDamage: sack ? cityDamageOf(city) : null
  });
};

// The interception of an AI landing (src/engine/aiLanding.js): the player's fleets in the city's
// waters against the transport, a sea battle.
const buildInterceptSetup = (state, pb) => {
  const def = (state.pendingDefenses || []).find((d) => d.id === pb.defenseId);
  const armies = def ? interceptArmies(state, def) : null;
  if (!armies) return null;
  const args = interceptArgs(state, def, armies);
  const city = state.regions[def.regionId];
  return buildSetupFromArmies({
    // On the city's waters: its first sea tile.
    tileContext: tileContextOf(state, city?.tile != null ? (getTiles().neighbors[city.tile].find((t) => getTiles().land[t] !== 1) ?? city.tile) : null, {}),
    battleType: 'naval', regionId: def.regionId, terrain: args.terrain, seed: pb.seed,
    attackerUnits: armies.attackerUnits, defenderUnits: armies.defenderUnits,
    attackerAgeId: args.attackerAgeId, defenderAgeId: args.defenderAgeId, generals: args.generals || {},
    fortLevel: 0, isCapital: false, infrastructure: 0, deposits: [], defenseReduction: 1, isAttackingFortification: false, attackerPenaltyMultiplier: 1,
    attackerNationId: def.aggressorId, defenderNationId: state.playerNationId, controllers: ['ai', 'player'], difficultyId: state.difficultyId || 'prince',
    powers: [[], []], reinforcements: [[], []], intel: { attackerSeesDefender: true }, regionBuildings: []
  });
};

export const buildInvasionSetup = (state, pendingBattle) => {
  if (isRaidKind(pendingBattle?.kind)) return buildRaidSetup(state, pendingBattle);
  if (pendingBattle?.kind === 'intercept') return buildInterceptSetup(state, pendingBattle);
  if (pendingBattle?.kind === 'naval') return buildNavalSetup(state, pendingBattle);
  if (pendingBattle?.kind === 'defense') return buildDefenseSetup(state, pendingBattle);
  if (pendingBattle?.kind === 'field') return buildFieldSetup(state, pendingBattle);
  if (pendingBattle?.kind === 'amphibious') return buildAmphibiousSetup(state, pendingBattle);
  const { fromRegionId, targetRegionId, seed, playerSide = 'attacker' } = pendingBattle;
  const v = validateInvasion(state, fromRegionId, targetRegionId, { ignoreCost: true, ignoreBattleLocks: true });
  if (!v.ok) return null;
  const attackerIds = new Set(pendingBattle.attackerUnitIds || v.attackerUnits.map((u) => u.id));
  const defenderIds = new Set(pendingBattle.defenderUnitIds || v.defenderUnits.map((u) => u.id));
  const attackerUnits = v.attackerUnits.filter((u) => attackerIds.has(u.id));
  const defenderUnits = v.defenderUnits.filter((u) => defenderIds.has(u.id));
  // Like every other kind: no attacker left (moved, disbanded, beaten elsewhere) is no battle to show.
  if (!attackerUnits.length) return null;
  const ctx = getInvasionBattleContext(state, { targetRegionId, targetRegion: v.targetRegion, defenderUnits });
  const ins = battleInputs(state, { attackerUnits, defenderUnits, cityId: targetRegionId, fromRegionId, militia: pendingBattle.militia || [] });
  const regionData = REGIONS_DATA[targetRegionId] || {};
  const fortLevel = (v.targetRegion.defenseLevel || 0) + getRegionModifier(state, targetRegionId, 'local.fortLevel').total;
  return buildSetupFromArmies({
    tileContext: tileContextOf(state, v.targetRegion.tile, { fromTile: attackerUnits.length ? unitTile(state, attackerUnits[0]) : state.regions[fromRegionId]?.tile ?? null, city: v.targetRegion }),
    regionId: targetRegionId,
    terrain: ctx.terrain,
    seed,
    attackerUnits: ins.attackerUnits,
    defenderUnits: ins.defenderUnits,
    attackerAgeId: ctx.attackerAgeId,
    defenderAgeId: ctx.defenderAgeId,
    generals: ctx.generals || {},
    fortLevel: Math.max(0, Math.round(fortLevel)),
    isCapital: !!regionData.isCapital,
    infrastructure: v.targetRegion.currentInfrastructure || 0,
    deposits: getDepositsFor(regionData.startOwner),
    defenseReduction: ctx.defenderDamageReductionMultiplier,
    isAttackingFortification: ctx.isAttackingFortification,
    attackerNationId: state.playerNationId,
    defenderNationId: v.targetRegion.owner,
    controllers: playerSide === 'attacker' ? ['player', 'ai'] : ['ai', 'player'],
    difficultyId: state.difficultyId || 'prince',
    powers: [
      getBattlePowers(state, state.playerNationId, ctx.attackerAgeId, attackerUnits, { allowNuclear: true }),
      getBattlePowers(state, v.targetRegion.owner, ctx.defenderAgeId, defenderUnits, { allowNuclear: false })
    ],
    reinforcements: [
      toReinforcements(state, pendingBattle, pendingBattle.attackerReinforcements, 0),
      toReinforcements(state, pendingBattle, pendingBattle.defenderReinforcements, 1)
    ],
    intel: { attackerSeesDefender: canSeeRegionDetails(state, targetRegionId) },
    regionBuildings: getRegionBattleBuildings(v.targetRegion),
    cityManifest: cityManifestOf(state, targetRegionId),
    cityDamage: cityDamageOf(v.targetRegion),
    economy: true,
    economyInputs: ins.economyInputs
  });
};

/**
 * How many units each side brings onto the field (strength above 0, reinforcements waiting at the
 * edge not counted): [attacker, defender]. A battle with 0 on either side is never opened
 * (TacticalBattleHost settles it on Auto through the outcome service): it would show an empty
 * field with nothing to command.
 */
export const setupSideCounts = (setup) => (setup?.sides || []).slice(0, 2).map((s) => (s?.units || []).filter((u) => u && u.strength > 0).length);
export const setupHasBothSides = (setup) => { const [a = 0, d = 0] = setupSideCounts(setup); return a > 0 && d > 0; };

/**
 * A key for "this exact battle": the seed, the place and every unit on each side. A mid-battle
 * checkpoint (battleStore.js) is only resumed into the battle with the same key: battle ids
 * (`b_<turn>_<counter>`) repeat from one game to the next, so a checkpoint left by another game's
 * battle must never be replayed into this one.
 */
export const setupKeyOf = (setup) => (setup
  ? `${setup.version}|${setup.seed}|${setup.regionId}|${setup.battleType}|${(setup.sides || []).map((s) => (s.units || []).map((u) => `${u.id}:${u.strength}`).join(',')).join('/')}`
  : null);

export const PLAYER_SIDE_INDEX =(pendingBattle) => (pendingBattle?.playerSide === 'defender' ? 1 : SIDE_ATTACKER);
